import { defaultClientConditions, defaultServerConditions, type Plugin } from "vite-plus";

// Workspace packages export their TypeScript under the `@freecorps/source` condition (generated by
// `vp pack`, `exports.devExports`), so dev, tests and type checks never need another package built first.
// Add this plugin to the vite.config.ts of every package whose dev, tests or build import a workspace
// package; its tsconfig needs `"customConditions": ["@freecorps/source"]` too (RFC 0002). A package that
// also packs must build declarations from a src-only tsconfig (`pack.tsconfig` or `pack.dts.tsconfig`),
// or tsgo also emits this file's .d.ts at the root.
const condition = "@freecorps/source";

export function workspaceSource(): Plugin {
  return {
    name: "brigade:workspace-source",
    // After framework plugins (the Cloudflare one sets its own conditions), for every environment.
    enforce: "post",
    configEnvironment(name, config) {
      const client = (config.consumer ?? (name === "client" ? "client" : "server")) === "client";
      const conditions =
        config.resolve?.conditions ?? (client ? defaultClientConditions : defaultServerConditions);
      if (conditions.includes(condition)) return;
      config.resolve = { ...config.resolve, conditions: [condition, ...conditions] };
    },
  };
}
